import {quickTrackWorkshop} from './music-quick-ui.js';
import {scoreSeconds} from './music-song.js';
import {GbaMaps} from './rom.js';
import {songUsage,describeSong,improvedLibraryName} from './music-names.js';
import {cryWorkshop} from './cry-ui.js';
import {uid} from './model.js';
import {musicAnalysis} from './music-analysis-ui.js';
import {musicComposer} from './music-compose-ui.js';
import {authoring,usedAuthoring} from './authoring-model.js';
import {musicTables,extractMusic,validateMusicAsset} from './music-assets.js';
import {renderMusic} from './music-preview.js';
import {digestBytes} from './playtest-core.js';

export function musicWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={source:null,table:null,query:'',limit:40,player:null,audio:null,worker:null,jobs:new Map(),serial:0,playSerial:0};
 async function task(type,payload){if(typeof Worker==='undefined'){await new Promise(r=>setTimeout(r,0));return type==='scan'?musicTables(new Uint8Array(payload.bytes)):type==='extract'?extractMusic(new Uint8Array(payload.bytes),payload.options.table,payload.options.songId,payload.options):renderMusic(payload.asset,payload.options);}if(!state.worker){state.worker=new Worker(new URL('./music-worker.js',import.meta.url),{type:'module'});state.worker.onmessage=e=>{const job=state.jobs.get(e.data.id);if(!job)return;state.jobs.delete(e.data.id);e.data.error?job.reject(Error(e.data.error)):job.resolve(e.data.result);};state.worker.onerror=()=>{for(const job of state.jobs.values())job.reject(Error('Music processing stopped. Reopen the music browser to retry.'));state.jobs.clear();state.worker.terminate();state.worker=null;};}return new Promise((resolve,reject)=>{const id=++state.serial;state.jobs.set(id,{resolve,reject});state.worker.postMessage({id,type,...payload});});}
 function previewControl(active){
  let button=$('#musicPreviewStop');
  if(!button&&active){const transport=document.createElement('footer');transport.id='musicPreviewTransport';button=document.createElement('button');button.id='musicPreviewStop';button.type='button';button.textContent='■ Stop preview';button.onclick=stop;transport.append(button);$('#dialogFooter').before(transport);}
  if(button){button.hidden=!active;button.parentElement.hidden=!active;}
  for(const id of ['quickStop','composeStop','referenceStop','remixStop','analysisStop','musicStop','sourceMusicStop']){const inline=$('#'+id);if(inline)inline.hidden=active;}
 }
 function stop(){state.playSerial++;try{state.player?.stop();}catch{}state.player=null;previewControl(false);}
 $('#dialog').addEventListener('close',stop);
 function addTracks(rows){const a=authoring(api.project());if(a.music.length+rows.length>512||JSON.stringify({...a,music:[...a.music,...rows]}).length>46e6)throw Error('This import exceeds the project music budget. Export a music pack and remove unused tracks first.');api.change(()=>a.music.push(...rows));}
 async function play(asset,request){
  if(request===undefined)stop();const serial=request??state.playSerial;if(serial!==state.playSerial)return null;previewControl(true);
  try{
   state.audio??=new (globalThis.AudioContext||globalThis.webkitAudioContext)();await state.audio.resume();if(serial!==state.playSerial)return null;api.toast('Rendering music preview…');const score=asset.arrangement?.score,full=score?scoreSeconds(score):20,seconds=Math.min(180,Math.max(1,full));const result=await task('render',{asset,options:{seconds,sampleRate:22050,gain:.65}});if(serial!==state.playSerial)return result;
   const buffer=state.audio.createBuffer(2,result.pcm.length/2,result.sampleRate);for(let ch=0;ch<2;ch++){const out=buffer.getChannelData(ch);for(let i=0;i<out.length;i++)out[i]=result.pcm[i*2+ch];}const source=state.audio.createBufferSource();source.buffer=buffer;if(score&&asset.arrangement.loop&&full<=180){source.loop=true;source.loopStart=scoreSeconds(score,score.loopStart??0);source.loopEnd=full;}source.connect(state.audio.destination);if(serial!==state.playSerial)return result;
   state.player=source;source.onended=()=>{if(state.player===source){state.player=null;previewControl(false);}};source.start();api.toast(score?(full>180?'Playing the first 3 minutes. Select a range to hear later bars.':source.loop?'Playing full song; intro plays once, then the marked section loops.':'Playing full song.'):'Playing 20-second ROM preview.');return result;
  }catch(error){if(serial===state.playSerial)stop();throw error;}
 }
 async function previewLoad(loader){stop();const serial=state.playSerial;previewControl(true);try{return await play(await loader(),serial);}catch(error){if(serial===state.playSerial)stop();throw error;}}
 async function previewId(id){const t=authoring(api.project()).music.find(t=>t.id===id);if(!t)throw Error('The music track is missing.');return previewLoad(()=>t.asset);}
 const cries=cryWorkshop(api);
 const composer=musicComposer({...api,quick:()=>quick.open(),tracks:()=>authoring(api.project()).music,add:asset=>addTracks([{id:uid(),name:asset.name,tags:[],asset}]),play,stop,editScore:(score,name,settings={})=>analysis.open({id:'',name,asset:null},score,settings),generateReference:t=>analysis.generateFrom(t),openLibrary:()=>open()});
 const analysis=musicAnalysis({...api,tracks:()=>authoring(api.project()).music,play,stop,arrange:options=>composer.open(options)});
 const quick=quickTrackWorkshop({...api,tracks:()=>authoring(api.project()).music,add:asset=>addTracks([{id:uid(),name:asset.name,tags:[],asset}]),play,stop,arrange:options=>composer.open(options),openLibrary:()=>open()});
 function open(){const renamed=authoring(api.project()).music.map(t=>[t,improvedLibraryName(t)]).filter(([,name])=>name);if(renamed.length)api.change(()=>renamed.forEach(([t,name])=>{t.name=name;t.asset.name=name;}));const tracks=authoring(api.project()).music,used=usedAuthoring(api.project()).music;api.modal('Music library',`<p>Import tracks and their required instruments/samples. Imported tracks remain saved here; the ROM receives only tracks assigned to enabled maps or events.</p><div class="studio-actions"><button id="musicCurrentROM" type="button" ${api.session()?'':'disabled'}>Browse opened ROM</button><button id="musicUploadROM" type="button">Upload another ROM</button><button id="musicCries" type="button" ${api.session()?'':'disabled'}>Pokémon cries</button><button id="musicQuick" type="button" class="primary">Quick Track · pick a vibe</button><button id="musicCompose" type="button">Advanced composer</button><button id="musicImportMIDI" type="button">Import MIDI</button><button id="musicImportPack" type="button">Import music pack</button><button id="musicStop" type="button">Stop preview</button></div><p class="studio-status">${tracks.length} library tracks · ${used.size} referenced</p><label>Find music<input id="musicSearch" type="search" placeholder="Track, map, source or tag"></label><div id="musicLibraryRows"></div><input id="musicROMFile" type="file" accept=".gba" hidden><input id="musicMIDIFile" type="file" accept=".mid,.midi,.rmi,audio/midi,audio/x-midi,audio/mid,application/octet-stream" hidden><input id="musicPackFile" type="file" accept=".json,application/json" hidden><p class="hint-line">Preview uses an offline MP2K renderer; PSG, modulation and reverb are approximate. ROM installation validates the opened ROM’s native song table. Compose tracks offline or arrange MIDI with original chip sounds and copied native instruments.</p>`,null,'Done');
  const draw=()=>{$('#musicLibraryRows').innerHTML=tracks.filter(t=>(t.name+' '+t.asset.sourceName+' '+(t.tags||'')).toLowerCase().includes($('#musicSearch').value.toLowerCase())).map(t=>`<article class="studio-record"><span><b>${esc(t.name)}</b><small>${esc(t.asset.sourceName)} · ${t.asset.trackCount} parts · ${(t.asset.sourceBytes/1024).toFixed(1)} KB · ${used.has(t.id)?'Used':'Library only'}</small></span><div class="studio-actions"><button data-music-preview="${t.id}" type="button">▶</button><button data-music-compose="${t.id}" type="button">Compose from this</button><button data-music-edit="${t.id}" type="button">Assign / edit</button></div></article>`).join('')||'<p>No matching tracks yet.</p>';document.querySelectorAll('[data-music-preview]').forEach(b=>b.onclick=()=>previewId(b.dataset.musicPreview).catch(api.error));document.querySelectorAll('[data-music-compose]').forEach(b=>b.onclick=()=>{try{stop();analysis.generateFrom(tracks.find(t=>t.id===b.dataset.musicCompose));}catch(e){api.error(e);}});document.querySelectorAll('[data-music-edit]').forEach(b=>b.onclick=()=>edit(tracks.find(t=>t.id===b.dataset.musicEdit)));};$('#musicSearch').oninput=draw;draw();$('#musicCries').onclick=()=>{stop();cries.open();};$('#musicQuick').onclick=()=>quick.open();$('#musicCompose').onclick=()=>composer.open();$('#musicImportMIDI').onclick=()=>$('#musicMIDIFile').click();$('#musicMIDIFile').onchange=e=>{const file=e.target.files[0];e.target.value='';composer.importFile(file).catch(api.error);};$('#musicStop').onclick=stop;$('#musicCurrentROM').onclick=()=>browse(api.session().reader.bytes,api.session().reader.filename,api.session().reader);$('#musicUploadROM').onclick=()=>$('#musicROMFile').click();$('#musicROMFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>32*1024*1024)throw Error('Use a GBA file up to 32 MB.');await browse(new Uint8Array(await file.arrayBuffer()),file.name);}catch(error){api.error(error);}};$('#musicImportPack').onclick=()=>$('#musicPackFile').click();$('#musicPackFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>16e6)throw Error('Keep one music pack below 16 MB.');const value=JSON.parse(await file.text()),assets=value.tracks||[value];if(assets.length>64)throw Error('Import up to 64 tracks per pack.');for(const asset of assets)validateMusicAsset(asset);addTracks(assets.map(asset=>({id:uid(),name:asset.name||'Imported track',tags:[],asset})));open();}catch(error){api.error(error);}};
 }
 async function browse(bytes,name,reader=null){try{api.modal('Scanning music','<p>Reading the song table without changing the ROM…</p>');const hash=await digestBytes(bytes),tables=await task('scan',{bytes});if(!reader){try{reader=await new GbaMaps(bytes).discover();}catch{reader=null;}}state.query='';state.limit=40;state.source={bytes,name,hash,reader,tables};state.table=tables[0];sourceBrowser();}catch(e){api.error(e);}}
 function sourceBrowser(){const source=state.source,table=state.table,r=new DataView(source.bytes.buffer,source.bytes.byteOffset,source.bytes.byteLength),usage=songUsage(source.reader);api.modal('Music in '+source.name,`<div class="studio-actions"><button id="musicBackLibrary" type="button">Library</button><button id="sourceMusicStop" type="button">Stop</button></div><label>Song table<select id="musicSongTable">${source.tables.map((t,i)=>`<option value="${i}" ${t.table===table.table?'selected':''}>${t.count} entries · ${t.references.length} references</option>`).join('')}</select></label><label>Find track<input id="sourceMusicSearch" type="search" placeholder="Song number or map" value="${esc(state.query)}"></label><label>Show<select id="sourceMusicKind"><option value="">Music and sound effects</option><option value="music">Music</option><option value="effect">Sound effects</option><option value="empty">Silent cues</option></select></label><div id="sourceMusicRows"></div><button id="sourceMusicMore" type="button">Show more tracks</button>`,null,'Done');$('#musicBackLibrary').onclick=open;$('#sourceMusicStop').onclick=stop;$('#musicSongTable').onchange=e=>{state.table=source.tables[+e.target.value];state.limit=40;sourceBrowser();};const details=id=>describeSong(source.bytes,table.table,id,{hash:source.hash,usage}),label=id=>details(id).name;const draw=()=>{const list=Array.from({length:table.count},(_,id)=>id).filter(id=>{const d=details(id);return(!$('#sourceMusicKind').value||d.kind===$('#sourceMusicKind').value)&&(id+' '+d.name+' '+d.maps.join(' ')).toLowerCase().includes(state.query.toLowerCase());});$('#sourceMusicRows').innerHTML=list.slice(0,state.limit).map(id=>{const info=details(id),count=info.count;return`<article class="studio-record"><span><b>${esc(label(id))}</b><small>#${id} · ${count} parts · ${info.kind==='effect'?'Sound effect':info.kind==='empty'?'Silent cue':'Music'}${info.maps.length?' · '+esc(info.maps.slice(0,3).join(' / ')):''}</small></span><div class="studio-actions"><button type="button" data-source-preview="${id}" ${count?'':'disabled'}>▶</button><button type="button" data-source-import="${id}" ${count?'':'disabled'}>Import</button></div></article>`;}).join('');$('#sourceMusicMore').hidden=list.length<=state.limit;document.querySelectorAll('[data-source-preview]').forEach(b=>b.onclick=()=>previewLoad(()=>get(+b.dataset.sourcePreview)).catch(api.error));document.querySelectorAll('[data-source-import]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;const asset=await get(+b.dataset.sourceImport);addTracks([{id:uid(),name:asset.name,tags:[],asset}]);api.toast('Track saved to the project library. It will compile only when assigned.');b.textContent='Imported';}catch(e){b.disabled=false;api.error(e);}});};const get=id=>task('extract',{bytes:source.bytes,options:{table:table.table,songId:id,name:label(id),sourceHash:source.hash,sourceName:source.name}});$('#sourceMusicSearch').oninput=e=>{state.query=e.target.value;state.limit=40;draw();};$('#sourceMusicKind').onchange=()=>{state.limit=40;draw();};$('#sourceMusicMore').onclick=()=>{state.limit+=40;draw();};draw();}
 function edit(t){api.modal('Music · '+t.name,`<label>Name<input id="musicName" maxlength="120" value="${esc(t.name)}"></label><label>Tags<input id="musicTags" value="${esc((t.tags||[]).join(', '))}" placeholder="Town, calm, battle…"></label><label>Assign to a map<select id="musicAssignMap"><option value="">Keep in library only</option>${api.project().maps.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><p>Assigning a map changes its background music. Scene actions can choose this track too.</p><div class="studio-actions"><button id="musicEditPreview" type="button">▶ Preview</button><button id="musicAnalysis" type="button">Notes & motifs</button><button id="musicRemix" type="button">Make a variation</button><button id="musicExportAsset" type="button">Export compatible music pack</button><button id="musicDeleteAsset" type="button" class="danger">Remove unused track</button></div>`,()=>{api.change(()=>{t.name=$('#musicName').value.trim()||t.name;t.tags=$('#musicTags').value.split(',').map(s=>s.trim()).filter(Boolean);const map=api.project().maps.find(m=>m.id===$('#musicAssignMap').value);if(map)map.audio={...map.audio,trackId:t.id};});api.toast('Music assignment saved.');},'Save');$('#musicAnalysis').onclick=()=>{try{analysis.open(t);}catch(e){api.error(e);}};$('#musicRemix').onclick=()=>composer.remix(t);$('#musicEditPreview').onclick=()=>previewId(t.id).catch(api.error);$('#musicExportAsset').onclick=()=>api.save(new Blob([JSON.stringify({...t.asset,name:t.name})],{type:'application/json'}),t.name.replace(/[^a-z0-9]+/gi,'_')+'.music.json');$('#musicDeleteAsset').onclick=()=>{if(usedAuthoring(api.project()).music.has(t.id)){api.toast('Remove this track’s map / event assignments first.');return;}api.change(()=>authoring(api.project()).music=authoring(api.project()).music.filter(v=>v.id!==t.id));open();};}
 return{state,open,browse,previewId,stop,composer,quick,analysis,cries};
}
